def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    last_opp = opp[-1]
    last_me = me[-1]

    # Count recent opponent behavior
    window = min(n, 12)
    recent = opp[n - window:]
    recent_c = 0
    for a in recent:
        if a == 'C':
            recent_c += 1
    recent_ratio = recent_c / window

    total_c = 0
    for a in opp:
        if a == 'C':
            total_c += 1
    total_ratio = total_c / n

    # Consecutive opponent defect run
    run_def = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            run_def += 1
        else:
            break

    run_coop = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C':
            run_coop += 1
        else:
            break

    # Only one prior move: be forgiving -- cooperate after a single defection
    # if it looked like noise, but defect against a hostile opener.
    if n == 1:
        return 'C' if last_opp == 'C' else 'C'

    if n == 2:
        # If opponent opened D followed by C, likely noise/probe -> cooperate.
        # If D followed by D, retaliate.
        if opp[0] == 'C':
            return 'C'
        if opp[1] == 'C':
            return 'C'
        return 'D'

    # Fully cooperative opponent: keep cooperating but probe rarely.
    if total_ratio >= 0.95 and run_def == 0:
        if n % 19 == 0 and rng.random() < 0.1:
            return 'D'
        return 'C'

    # Opponent clearly hostile: mostly defect, with rare probes.
    if recent_ratio <= 0.1 and run_def >= 4:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Heavy exploitation: opponent defects much more than cooperates overall.
    if total_ratio < 0.35 and recent_ratio < 0.4:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Recover from mutual defection spirals: if both have been defecting,
    # attempt to restart cooperation, but only if opponent isn't purely hostile.
    if last_opp == 'D' and last_me == 'D':
        # If opponent has cooperated at least sometimes recently, try C.
        if recent_ratio >= 0.35:
            if run_def >= 3:
                # Opponent is in a defection streak; one more D but try C soon.
                if rng.random() < 0.25:
                    return 'C'
                return 'D'
            if rng.random() < 0.6:
                return 'C'
            return 'D'
        else:
            # Opponent mostly defecting; defect but probe.
            if rng.random() < 0.1:
                return 'C'
            return 'D'

    # Opponent just defected; we cooperated last.
    if last_opp == 'D' and last_me == 'C':
        if run_def >= 3:
            # Sustained defection -> retaliate, rare forgiveness.
            if rng.random() < 0.07:
                return 'C'
            return 'D'
        if recent_ratio >= 0.6:
            # Opponent generally nice; probably noise -> forgive.
            if rng.random() < 0.75:
                return 'C'
            return 'D'
        # Moderate: retaliate once, but be forgiving.
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # Opponent just cooperated.
    if last_opp == 'C':
        # If we defected last, return to cooperation.
        if last_me == 'D':
            return 'C'
        # Detect exploitation pattern: opponent often defects right after
        # a block of cooperation. Look for C...CD.
        if n >= 4:
            tail = opp[-4:]
            if tail[0] == 'C' and tail[1] == 'C' and tail[2] == 'C' and tail[3] == 'D':
                return 'D'
        # Otherwise cooperate, with a rare probe if opponent never defected.
        if run_coop >= 5 and total_ratio > 0.9:
            if rng.random() < 0.03:
                return 'D'
        return 'C'

    return 'C'
